 * block is enough; we keep threads=32 for warp efficiency but only thread 0 acts.
 */
__global__ void softmax_xent_grad_kernel(float *Z3, const float *b3,
                                         const int *d_ybatch,
                                         float *d_loss_accum,
                                         int OUT, int B)
{
