    \node[box, right=of r1] (rR) {rank $R{-}1$ slice\\\scriptsize fwd/bwd $\to g^{(R-1)}$};
    \node[red, below=of r1] (allred) {\texttt{MPI\_Allreduce(SUM)} on flat gradient buffer};
    \node[upd, below=of allred] (upd) {every rank: \texttt{mlp\_sgd\_update}($m,g,\mathrm{lr},B$)};
    \draw[ar] (r0)--(allred);
    \draw[ar] (r1)--(allred);
    \draw[ar] (rR)--(allred);
    \draw[ar] (allred)--(upd);
  \end{tikzpicture}
  \caption{MPI data-parallel SGD with a single \texttt{Allreduce} over the
