  \begin{tikzpicture}[
    node distance=6mm and 10mm,
    hst/.style={draw, rounded corners, align=center, minimum height=6mm, fill=blue!8},
    dev/.style={draw, rounded corners, align=center, minimum height=6mm, fill=green!10},
    krn/.style={draw, rounded corners, align=center, minimum height=6mm, fill=orange!15, font=\small},
    ar/.style={-{Latex[length=2mm]}},
  ]
